CREATE TABLE `notice_cursor` (
	`name` text PRIMARY KEY,
	`occurred_at` integer NOT NULL,
	`event_id` text NOT NULL,
	CONSTRAINT "notice_cursor_single" CHECK("name" in ('access_notices'))
) STRICT;
