CREATE TABLE `notification_delivery` (
	`id` text PRIMARY KEY,
	`account_id` text NOT NULL,
	`subject` text NOT NULL,
	`ref` text NOT NULL,
	`channel` text NOT NULL,
	`status` text NOT NULL,
	`attempts` integer NOT NULL,
	`claimed_at` integer NOT NULL,
	`finished_at` integer,
	CONSTRAINT `fk_notification_delivery_account_id_account_id_fk` FOREIGN KEY (`account_id`) REFERENCES `account`(`id`),
	CONSTRAINT "notification_delivery_subject_known" CHECK("subject" in ('morning', 'weekly', 'notice')),
	CONSTRAINT "notification_delivery_channel_known" CHECK("channel" in ('push')),
	CONSTRAINT "notification_delivery_status_known" CHECK("status" in ('claimed', 'sent', 'skipped')),
	CONSTRAINT "notification_delivery_ref_present" CHECK(length("ref") between 1 and 64),
	CONSTRAINT "notification_delivery_attempts_positive" CHECK("attempts" >= 1),
	CONSTRAINT "notification_delivery_finished_when_not_claimed" CHECK(("status" = 'claimed') = ("finished_at" is null))
) STRICT;
