CREATE TABLE `notification_preference` (
	`account_id` text PRIMARY KEY,
	`morning_at` text,
	`weekly_at` text,
	`created_at` integer NOT NULL,
	`created_by` text NOT NULL,
	`updated_at` integer NOT NULL,
	`updated_by` text NOT NULL,
	`version` integer NOT NULL,
	CONSTRAINT `fk_notification_preference_account_id_account_id_fk` FOREIGN KEY (`account_id`) REFERENCES `account`(`id`),
	CONSTRAINT `fk_notification_preference_created_by_account_id_fk` FOREIGN KEY (`created_by`) REFERENCES `account`(`id`),
	CONSTRAINT `fk_notification_preference_updated_by_account_id_fk` FOREIGN KEY (`updated_by`) REFERENCES `account`(`id`),
	CONSTRAINT "notification_preference_morning_quarter_hour" CHECK("morning_at" is null or ("morning_at" glob '[0-2][0-9]:[0-5][0-9]' and "morning_at" < '24:00' and substr("morning_at", 4, 2) in ('00', '15', '30', '45'))),
	CONSTRAINT "notification_preference_weekly_quarter_hour" CHECK("weekly_at" is null or ("weekly_at" glob '[0-2][0-9]:[0-5][0-9]' and "weekly_at" < '24:00' and substr("weekly_at", 4, 2) in ('00', '15', '30', '45'))),
	CONSTRAINT "notification_preference_version_positive" CHECK("version" >= 1),
	CONSTRAINT "notification_preference_updated_after_created" CHECK("updated_at" >= "created_at")
) STRICT;
