CREATE TABLE `push_subscription` (
	`id` text PRIMARY KEY,
	`account_id` text NOT NULL,
	`session_id` text UNIQUE,
	`endpoint` text NOT NULL UNIQUE,
	`p256dh` text NOT NULL,
	`auth` text NOT NULL,
	`device_label` text NOT NULL,
	`created_at` integer NOT NULL,
	`last_sent_at` integer,
	CONSTRAINT `fk_push_subscription_account_id_account_id_fk` FOREIGN KEY (`account_id`) REFERENCES `account`(`id`),
	CONSTRAINT `fk_push_subscription_session_id_session_id_fk` FOREIGN KEY (`session_id`) REFERENCES `session`(`id`) ON DELETE SET NULL,
	CONSTRAINT "push_subscription_endpoint_https" CHECK("endpoint" like 'https://%' and length("endpoint") <= 2048),
